<template><div class="business-console"><div class="console-header"><div><h1>{{title}}</h1><p>{{descriptions[type]}}</p></div><el-button @click="load" :loading="loading">刷新</el-button></div><el-alert v-if="!paymentsEnabled" title="支付及资金操作暂未开放，退款、结算和提现处理已关闭" type="info" :closable="false" show-icon /><el-form inline class="filters" @submit.prevent="search"><el-form-item><el-input v-model="query.keyword" :placeholder="type==='orders'||type==='aftersales'?'输入订单编号':['members','shops'].includes(type)?'昵称 / 店铺名 / 5位用户编号':'输入标题或昵称'" clearable @keyup.enter="search" /></el-form-item><el-form-item v-if="type!=='audit'"><el-select v-model="query.status" placeholder="全部状态" clearable style="width:160px"><el-option v-for="s in availableStatuses" :key="s" :label="type==='members'&&s==='ACTIVE'?'正常':statusText[s]" :value="s" /></el-select></el-form-item><el-form-item v-if="type==='members'"><el-checkbox v-model="certOnly" @change="query.status='';search()">按历史认证状态筛选</el-checkbox></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" show-icon style="margin-bottom:14px" /><el-table :data="rows" v-loading="loading" empty-text="暂无相关记录" stripe><el-table-column prop="id" label="ID" width="70" /><template v-if="type==='listings'"><el-table-column label="发布类型" width="90"><template #default="s">{{s.row.businessType==='PLAYER_ITEM'?(s.row.kind==='SERVICE'?'道具出售':'求购'):'历史代练'}}</template></el-table-column><el-table-column prop="title" label="标题" min-width="200" show-overflow-tooltip /><el-table-column prop="nickname" label="发布者" /><el-table-column prop="game" label="游戏" /><el-table-column label="价格"><template #default="s">{{amount(s.row.priceCents)}}</template></el-table-column></template><template v-if="type==='members'"><el-table-column prop="userNo" label="用户编号" width="120" /><el-table-column prop="username" label="账号" min-width="130" /><el-table-column prop="nickname" label="昵称" /><el-table-column label="店铺认证"><template #default="s"><el-tag>{{statusText[s.row.playerProfile?.shopStatus||'NONE']}}</el-tag></template></el-table-column><el-table-column label="实名认证"><template #default="s">{{s.row.playerProfile?.realnameStatus==='VERIFIED'?'已实名':'未实名'}}</template></el-table-column><el-table-column label="等级 / 会员"><template #default="s">Lv.{{s.row.playerProfile?.level||1}} · {{s.row.playerProfile?.membershipActive?'会员':'非会员'}}</template></el-table-column><el-table-column label="余额"><template #default="s">{{amount(s.row.balanceCents)}}</template></el-table-column></template><template v-if="type==='shops'"><el-table-column prop="shopName" label="店铺名称" min-width="180" /><el-table-column prop="nickname" label="店主" /><el-table-column prop="phone" label="已验证手机号" min-width="140" /><el-table-column label="实名状态"><template #default="s">{{s.row.realnameStatus==='VERIFIED'?'已实名':'未实名'}}</template></el-table-column></template><template v-if="type==='orders'||type==='aftersales'"><el-table-column prop="orderNo" label="订单编号" min-width="230" /><el-table-column prop="title" label="交易内容" min-width="180" show-overflow-tooltip /><el-table-column :prop="type==='orders'?'buyerName':'nickname'" label="用户" /><el-table-column v-if="type==='orders'" prop="workerName" label="卖家" /><el-table-column label="金额"><template #default="s">{{amount(s.row.amountCents)}}</template></el-table-column></template><template v-if="type==='withdrawals'"><el-table-column prop="nickname" label="申请人" /><el-table-column label="金额"><template #default="s">{{amount(s.row.amountCents)}}</template></el-table-column><el-table-column prop="accountName" label="收款人" /><el-table-column prop="accountNumber" label="收款账号" min-width="180" show-overflow-tooltip /></template><template v-if="type==='audit'"><el-table-column prop="adminId" label="操作人ID" /><el-table-column prop="action" label="操作" min-width="170" /><el-table-column prop="targetId" label="业务ID" /><el-table-column prop="note" label="处理说明" min-width="220" /></template><el-table-column v-if="type!=='audit'" label="状态" width="100"><template #default="s"><el-tag :type="tagType(type==='shops'?s.row.shopStatus:s.row.status)">{{type==='members'&&s.row.status==='ACTIVE'?'正常':statusText[type==='shops'?s.row.shopStatus:s.row.status]}}</el-tag></template></el-table-column><el-table-column prop="createdAt" label="创建时间" min-width="175"><template #default="s">{{s.row.createdAt?.replace('T',' ')}}</template></el-table-column><el-table-column v-if="type!=='audit'" label="操作" width="105" fixed="right"><template #default="s"><el-button link type="primary" @click="inspect(s.row)">查看 / 处理</el-button></template></el-table-column></el-table><el-pagination class="pagination" v-model:current-page="query.page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="load" /><el-drawer v-model="drawer" :title="title+' · 详情'" size="560px" destroy-on-close><template v-if="selected"><el-descriptions :column="1" border><el-descriptions-item v-for="field in detailFields" :key="field[0]" :label="field[1]">{{display(field[0],selected[field[0]])}}</el-descriptions-item></el-descriptions><div v-if="proofs.length" class="evidence"><h3>图片与凭证</h3><el-image v-for="p in proofs" :key="p" :src="mediaUrl(p)" role="button" tabindex="0" aria-label="预览凭证" @click="previewImages(proofs,p)" @keydown.enter="previewImages(proofs,p)" fit="cover" style="width:100px;height:100px;margin:5px" /></div><div v-if="selected.deliveries?.length" class="section"><h3>道具交付凭证</h3><div v-for="p in selected.deliveries" :key="p.id"><p>{{p.note}} · {{p.createdAt}}</p><el-image v-for="src in parseImages(p.images)" :key="src" :src="mediaUrl(src)" @click="previewImages(parseImages(p.images),src)" fit="cover" style="width:90px;height:70px;margin:5px" /></div></div><div v-if="selected.updates?.length" class="section"><h3>交付进度</h3><el-timeline><el-timeline-item v-for="p in selected.updates" :key="p.id" :timestamp="p.createdAt"><b>{{p.percent}}%</b> {{p.note}}<div><el-image v-for="src in parseImages(p.images)" :key="src" :src="mediaUrl(src)" role="button" tabindex="0" aria-label="预览交付图片" @click="previewImages(parseImages(p.images),src)" @keydown.enter="previewImages(parseImages(p.images),src)" style="width:90px;height:70px;margin:5px" fit="cover" /></div></el-timeline-item></el-timeline></div><div v-if="canProcess" class="decision"><h3>处理意见</h3><el-input v-model="note" type="textarea" :rows="3" maxlength="500" show-word-limit placeholder="请填写具体审核或处理说明，至少 2 个字" /><el-alert v-if="['aftersales','withdrawals'].includes(type)" title="通过后进入支付渠道处理流程。仅微信已验证的结果会标记真实退款或到账。" type="warning" :closable="false" style="margin:16px 0" /><div class="decision-actions"><template v-if="type==='members'"><el-button v-if="canStatus" type="danger" plain :disabled="saving" @click="decide(selected.status==='ACTIVE'?'block':'unblock')">{{selected.status==='ACTIVE'?'停用账号':'恢复账号'}}</el-button></template><template v-else><el-button v-if="selected.status==='PENDING'" type="primary" :loading="saving" @click="decide('approve')">{{type==='aftersales'?'同意退款':type==='withdrawals'?'批准提现':'审核通过'}}</el-button><el-button v-if="selected.status==='PENDING'" :disabled="saving" @click="decide('reject')">不通过</el-button><el-button v-if="type==='listings'&&selected.status==='ACTIVE'" type="danger" plain :disabled="saving" @click="decide('offline')">下架</el-button></template></div></div><div v-if="canFinance&&['WAIT_PAY','REFUNDING','REFUND_EXCEPTION'].includes(selected.status)" class="decision"><h3>渠道核对与退款处理</h3><el-input v-model="note" type="textarea" maxlength="500" placeholder="填写核对或重试原因，至少 2 个字" /><div class="decision-actions"><el-button :loading="saving" @click="finance('refresh')">核对渠道状态</el-button><el-button v-if="selected.status==='REFUND_EXCEPTION'&&selected.providerState==='CLOSED'" :loading="saving" type="warning" @click="finance('retryRefund')">重新提交已关闭的退款</el-button></div><p v-if="selected.providerState==='ABNORMAL'">请先在微信商户平台处理异常，再核对结果。</p></div><ShopDisclosureEditor v-if="type==='shops'&&selected.shopStatus!=='NONE'" :key="selected.id+':'+selected.shopRevision" :member="selected" @saved="drawer=false;load()" /><BenefitsEditor v-if="type==='members'" :key="selected.id+':'+(selected.benefitsRevision||0)" :member="selected" @saved="drawer=false;load()" /></template></el-drawer><el-image-viewer v-if="preview.open" teleported :url-list="preview.urls" :initial-index="preview.index" @close="closePreview" /></div></template>
<script setup>
import BenefitsEditor from './BenefitsEditor.vue'
import ShopDisclosureEditor from './ShopDisclosureEditor.vue'
import auth from '@/plugins/auth';import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue';import {useRoute} from 'vue-router';import {ElMessage,ElMessageBox} from 'element-plus';import {listBusiness,businessConfig,moderate,handleAftersale,handleWithdrawal,orderDetail,reconcileOrder,amount,statusText,mediaUrl} from '@/api/boost'
import {authorizeMedia} from '@/utils/boostMedia'
import {getToken} from '@/utils/auth'
const route=useRoute(),type=computed(()=>route.path.split('/').filter(Boolean).pop()),titles={listings:'发布审核',shops:'店铺认证审核',members:'玩家管理',orders:'订单管理',aftersales:'售后处理',withdrawals:'提现审核',audit:'业务操作记录'},title=computed(()=>titles[type.value]||'业务管理'),descriptions={shops:'审核店铺披露资料与已验证手机号；用户只可首次提交，后续由后台更正，保留完整历史。',listings:'审核道具出售与求购，让真实内容进入市场。',members:'管理玩家状态，查看会员与成长资料。',orders:'查看交易状态、参与者与交付记录。',aftersales:'结合双方沟通及交付凭证处理争议。',withdrawals:'核对提现申请，拒绝后自动退回冻结余额。',audit:'每一次后台业务处理，都有可追溯的记录。'}
const paymentsEnabled=ref(false)
const query=reactive({keyword:'',status:'',page:1}),certOnly=ref(false),rows=ref([]),total=ref(0),loading=ref(false),error=ref(''),drawer=ref(false),selected=ref(null),note=ref(''),saving=ref(false)
const availableStatuses=computed(()=>({shops:['NONE','PENDING','APPROVED','REJECTED'],listings:['PENDING','ACTIVE','REJECTED','OFFLINE','RESERVED','SOLD','MATCHED'],members:certOnly.value?['PENDING','APPROVED','REJECTED','NONE']:['ACTIVE','BLOCKED'],orders:['WAIT_DELIVERY','WAIT_CONFIRM','WAIT_PAY','WAIT_START','IN_PROGRESS','REVIEW','COMPLETED','AFTERSALE','REFUNDING','REFUND_EXCEPTION','REFUNDED','CANCELLED'],aftersales:['PENDING','REFUNDING','REFUND_EXCEPTION','REFUNDED','REJECTED'],withdrawals:['PENDING','PROCESSING','WAIT_USER_CONFIRM','PAID','SIMULATED_PAID','REJECTED','FAILED']}[type.value]||[]))
const fields={shops:[['shopName','店铺名称'],['nickname','店主'],['userNo','用户编号'],['phone','已验证手机号'],['phoneVerifiedAt','手机号验证时间'],['shopRevision','资料版本'],['shopIntro','店铺介绍'],['shopStatus','店铺认证'],['realnameStatus','实名状态'],['shopReviewNote','审核说明']],listings:[['title','标题'],['nickname','发布者'],['game','游戏'],['zone','区服'],['platform','设备'],['businessType','业务类型'],['itemCategory','道具分类'],['quantity','数量'],['itemDetails','道具介绍'],['deliveryTerms','交付约定'],['pricingMode','计价方式'],['priceCents','标价'],['reservedQuantity','预订件数'],['soldQuantity','已售件数'],['description','描述'],['status','状态'],['reviewNote','审核说明']],members:[['userNo','用户编号'],['username','账号'],['nickname','昵称'],['membershipLabel','会员状态'],['level','等级'],['growthPoints','成长值'],['shopStatus','店铺认证'],['realnameStatus','实名状态'],['status','账户状态'],['balanceCents','可提现余额'],['reviewNote','审核说明']],orders:[['orderNo','订单号'],['title','内容'],['buyerName','用户'],['workerName','卖家'],['itemCategory','道具分类'],['quantity','数量'],['itemDetails','道具介绍'],['deliveryTerms','交付约定'],['unitPriceCents','每件单价'],['amountCents','实付款'],['originalCents','原价'],['discountCents','优惠'],['status','状态'],['providerState','渠道状态'],['providerError','渠道异常'],['expiresAt','付款截止'],['note','需求说明'],['paymentMode','支付方式'],['createdAt','创建时间']],aftersales:[['orderNo','订单'],['nickname','申请人'],['reason','原因'],['description','说明'],['amountCents','退款金额'],['status','状态'],['reply','处理结果']],withdrawals:[['nickname','申请人'],['amountCents','提现金额'],['accountName','收款人'],['accountNumber','收款账号'],['status','状态'],['note','处理说明']]};const canReview=computed(()=>auth.hasPermi(`boost:${type.value}:review`)),canStatus=computed(()=>type.value==='members'&&auth.hasPermi('boost:members:status')),canFinance=computed(()=>paymentsEnabled.value&&type.value==='orders'&&auth.hasPermi('boost:finance:reconcile'));const detailFields=computed(()=>fields[type.value]||[]),canProcess=computed(()=>selected.value&&(!['aftersales','withdrawals'].includes(type.value)||paymentsEnabled.value)&&(canReview.value||canStatus.value)&&(type.value==='members'||(['shops','listings','aftersales','withdrawals'].includes(type.value)&&['PENDING','ACTIVE'].includes(selected.value.status)))),proofs=computed(()=>[...parseImages(selected.value?.shopProof||selected.value?.images||selected.value?.proof),...parseImages(selected.value?.detailImages)])
function parseImages(v){try{return JSON.parse(v||'[]')}catch{return []}}function display(k,v){if(k==='pricingMode')return v==='UNIT'?'单价 × 数量':'历史整批';if(k.endsWith('Cents'))return amount(v);if(k==='status'&&type.value==='members'&&v==='ACTIVE')return '正常';if(['status','shopStatus','realnameStatus','certification'].includes(k))return statusText[v]||v;return v??'—'}function tagType(s){return ['REJECTED','BLOCKED','AFTERSALE'].includes(s)?'danger':['APPROVED','ACTIVE','COMPLETED'].includes(s)?'success':'info'}
let loadVersion=0,detailVersion=0
const preview=reactive({open:false,urls:[],index:0});let previewVersion=0
function closePreview(){previewVersion++;preview.open=false;preview.urls=[]}
watch([drawer,selected],closePreview)
onBeforeUnmount(closePreview)
async function previewImages(paths,current){
 const version=++previewVersion,token=getToken()
 await authorizeMedia(paths)
 if(version!==previewVersion||token!==getToken()||!drawer.value)return
 const available=paths.map(path=>({path,url:mediaUrl(path)})).filter(item=>item.url)
 const index=available.findIndex(item=>item.path===current)
 if(index<0){ElMessage.warning('图片暂时无法查看，请刷新后重试');return}
 preview.urls=available.map(item=>item.url);preview.index=index;preview.open=true
}
async function load(){const version=++loadVersion;loading.value=true;error.value='';try{const mode=await businessConfig();if(version!==loadVersion)return;paymentsEnabled.value=mode.data.paymentsEnabled!==false;const r=await listBusiness(type.value,{...query,filter:certOnly.value?'certification':''});if(version!==loadVersion)return;rows.value=r.data.items;total.value=r.data.total}catch(e){if(version===loadVersion)error.value=e.message||'加载失败'}finally{if(version===loadVersion)loading.value=false}}
function search(){query.page=1;load()}function reset(){Object.assign(query,{keyword:'',status:'',page:1});certOnly.value=false;load()}
watch(type,()=>{detailVersion++;drawer.value=false;selected.value=null;rows.value=[];total.value=0;reset()},{immediate:true})
async function inspect(row){const version=++detailVersion;selected.value=type.value==='shops'?{...row,status:row.shopStatus}:type.value==='members'?{...row,...row.playerProfile,membershipLabel:row.playerProfile?.membershipActive?'会员':'非会员'}:row;note.value='';drawer.value=true;if(type.value==='orders'){try{const result=await orderDetail(row.id);if(version===detailVersion)selected.value=result.data}catch(e){if(version===detailVersion)ElMessage.error(e.message)}}}
async function decide(action){
 if(saving.value)return;if(['aftersales','withdrawals'].includes(type.value)&&!paymentsEnabled.value){ElMessage.warning('支付及资金操作暂未开放');return}if(note.value.trim().length<2){ElMessage.warning('请填写至少 2 个字的处理说明');return}
 const targetType=type.value,targetId=selected.value.id,data={action,note:note.value,...(type.value==='shops'?{expectedRevision:selected.value.shopRevision||0}:{})};saving.value=true
 try{await ElMessageBox.confirm('确认执行此操作？结果会通知相关用户并记录在业务日志中。','确认处理',{type:'warning'});if(type.value!==targetType||selected.value?.id!==targetId)return;
  if(targetType==='aftersales')await handleAftersale(targetId,data);else if(targetType==='withdrawals')await handleWithdrawal(targetId,data);else await moderate(targetType,targetId,data);
  ElMessage.success('处理成功');drawer.value=false;load()
 }catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'处理失败')}finally{saving.value=false}
}
async function finance(action){if(saving.value)return;if(!paymentsEnabled.value){ElMessage.warning('支付及资金操作暂未开放');return;}if(note.value.trim().length<2){ElMessage.warning('请填写至少 2 个字的处理原因');return}const id=selected.value.id,typeAtStart=type.value;saving.value=true;try{await ElMessageBox.confirm('核对将以渠道真实结果更新订单。退款重试仅适用于渠道已关闭的退款。','确认处理');if(type.value!==typeAtStart||selected.value?.id!==id)return;await reconcileOrder(id,{action,note:note.value});await inspect(selected.value);load();ElMessage.success('处理完成，请查看最新状态')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'核对失败')}finally{saving.value=false}}
</script>
<style scoped>.business-console{padding:28px 30px}.console-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:28px}.console-header h1{font-size:26px;margin:0 0 9px}.console-header p{font-size:13px;color:#8c8f98;margin:0}.filters{padding:18px 18px 0;background:#f8f9fb;border-radius:10px;margin-bottom:18px}.pagination{justify-content:flex-end;margin-top:22px}.decision{padding:24px 0}.decision h3,.evidence h3,.section h3{font-size:15px}.decision-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px}.decision-actions .el-button{margin:0}.evidence,.section{margin-top:24px}</style>
